def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("nanoseconds must be an integer")
    if tz is not None and not isinstance(tz, datetime.tzinfo):
        raise ValueError("tz must be a datetime.tzinfo object")
    if nanoseconds < 0 or nanoseconds >= 24 * 60 * 60 * 1000000000:
        raise ValueError("nanoseconds must be a valid time")
    if tz is not None:
        return datetime.time(nanoseconds // 1000000000, (nanoseconds // 1000000) % 1000, (nanoseconds // 1000) % 1000, tzinfo=tz)
    else:
        return datetime.time(nanoseconds // 1000000000, (nanoseconds // 1000000) % 1000, (nanoseconds // 1000) % 1000)
