def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        use_count = {}

        def _wrapper(*args, **kwargs):
            if typed:
                key = args[0]
            else:
                key = make_key(args, kwargs)

            if key in cache:
                use_count[key] += 1
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            use_count[key] = 1

            if len(cache) > maxsize:
                for key, _ in sorted(use_count.items(), key=lambda x: x[1]):
                    if key in cache:
                        del cache[key]
                        del use_count[key]
                        break

            return result

        return _wrapper

    return wrapper
