def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, Declaration):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(_normalizeargs(item))
        else:
            raise ValueError("Invalid argument type: {}".format(type(item)))
    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if self.initial_value is not None:
        self.bins = [self.initial_value] * self.num_bins
    else:
        self.bins = self.make_bins()

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins and edges must be equal.")
    if any(edge < 0 for edge in edges):
        raise ValueError("Edges must be non-negative.")
    if any(bin < 0 for bin in bins):
        raise ValueError("Bins must be non-negative.")

    total = 0
    for i in range(len(bins)):
        total += (edges[i + 1] - edges[i]) * bins[i]

    return total

