def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generates a partial default observer schema from a partial Kubernetes resource
    defined by the input dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resource
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema
    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("Input must be a dictionary")

    if first_level:
        # If the input dictionary represents the whole observer schema,
        # copy the values of the identifying fields from the manifest file.
        result = {
            "apiVersion": manifest_dict.get("apiVersion"),
            "kind": manifest_dict.get("kind"),
            "metadata": {
                "name": manifest_dict.get("metadata", {}).get("name"),
                "namespace": manifest_dict.get("metadata", {}).get("namespace"),
            },
        }
    else:
        # Otherwise, create a new dictionary from the input dictionary
        # and replace all non-list and non-dict values by None.
        result = {}
        for key, value in manifest_dict.items():
            if isinstance(value, (list, dict)):
                result[key] = value
            else:
                result[key] = None

    return result

