def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not os.path.exists(path):
            raise ValueError(f"Path {path} does not exist")
        if not os.path.isdir(path):
            raise ValueError(f"Path {path} is not a directory")
        if not os.path.isfile(os.path.join(path, "ocfl_layout.json")):
            raise ValueError(f"Path {path} does not contain an OCFL layout file")
        if not os.path.isfile(os.path.join(path, "ocfl_inventory.json")):
            raise ValueError(f"Path {path} does not contain an OCFL inventory file")
        if not os.path.isfile(os.path.join(path, "ocfl_object.json")):
            raise ValueError(f"Path {path} does not contain an OCFL object file")
        if not os.path.isfile(os.path.join(path, "ocfl_state.json")):
            raise ValueError(f"Path {path} does not contain an OCFL state file")
        if not os.path.isfile(os.path.join(path, "ocfl_validation.json")):
            raise ValueError(f"Path {path} does not contain an OCFL validation file")
        return True
    except Exception as e:
        return False
