def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Indent the output by the specified number of spaces
    indentation = " " * indent

    # If debug is True, include the object's memory address in the output
    if debug:
        output = f"{indentation}<{self.__class__.__name__} object at {hex(id(self))}>"
    else:
        output = f"{indentation}<{self.__class__.__name__}>"

    # Recursively pretty-print the object's attributes
    for attr in self.__dict__:
        value = getattr(self, attr)
        if isinstance(value, (list, tuple)):
            output += f"\n{indentation}  {attr} = ["
            for item in value:
                output += f"\n{indentation}    {item},"
            output += f"\n{indentation}  ]"
        elif isinstance(value, dict):
            output += f"\n{indentation}  {attr} = {"
            for key, val in value.items():
                output += f"\n{indentation}    {key}: {val},"
            output += f"\n{indentation}  }"
        else:
            output += f"\n{indentation}  {attr} = {value}"

    # Close the output string
    output += f"\n{indentation}</{self.__class__.__name__}>"

    return output

