def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Command must be a string")
        if not command:
            raise ValueError("Command cannot be empty")
    if not isinstance(args, (list, tuple)):
        raise ValueError("Args must be a list or tuple")
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("Args must be strings")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("Cwd must be a string")
    if not isinstance(verbose, bool):
        raise ValueError("Verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("Hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise ValueError("Env must be a dictionary")

    # Create a subprocess and execute the command
    process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Read the output and error streams
    stdout, stderr = process.communicate()

    # Check the return code and raise an exception if it's not 0
    if process.returncode != 0:
        raise RuntimeError("Command failed with return code %d" % process.returncode)

    # Return the output and error streams
    return stdout, stderr

