def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Check if the version directories are in the correct sequence
    if not version_dirs or len(version_dirs) == 0:
        raise ValueError("version_dirs must not be empty")
    if not all(isinstance(version_dir, str) for version_dir in version_dirs):
        raise TypeError("version_dirs must be a list of strings")
    if not all(version_dir.isdigit() for version_dir in version_dirs):
        raise ValueError("version_dirs must be a list of version numbers")
    if not all(version_dir.startswith("v") for version_dir in version_dirs):
        raise ValueError("version_dirs must start with 'v'")

    # Check if the inventory files exist for each version
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

    # Check if the content digests are different from those in the root inventory
    root_inventory_file = os.path.join(version_dirs[0], "inventory.json")
    root_inventory = json.load(open(root_inventory_file))
    for version_dir in version_dirs[1:]:
        inventory_file = os.path.join(version_dir, "inventory.json")
        inventory = json.load(open(inventory_file))
        for content_digest in inventory["content_digests"]:
            if content_digest not in root_inventory["content_digests"]:
                raise ValueError(f"Content digest {content_digest} not found in root inventory")

    return True
