def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string or not alphabet:
        raise ValueError("string and alphabet cannot be empty")
    if not all(c in alphabet for c in string):
        raise ValueError("string contains invalid characters")
    if len(alphabet) < 2:
        raise ValueError("alphabet must have at least 2 characters")

    base = len(alphabet)
    num = 0
    for i, c in enumerate(string):
        num += alphabet.index(c) * (base ** i)

    return num

