def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        return _split_posix(s)
    elif platform == 'nt':
        return _split_windows(s)
    else:
        raise ValueError("Invalid platform specified")

def _split_posix(s):
    # Use shlex.split() for POSIX platform
    return shlex.split(s)

def _split_windows(s):
    # Use a custom split function for Windows platform
    # This function will split the string based on spaces, but will also
    # handle quotes and escaping of quotes
    result = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
            continue
        if s[i] == '"':
            # Handle quoted string
            i += 1
            start = i
            while i < len(s) and s[i] != '"':
                i += 1
            result.append(s[start:i])
            i += 1
            continue
        # Handle non-quoted string
        start = i
        while i < len(s) and s[i] != ' ':
            i += 1
        result.append(s[start:i])
    return result
