    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        try:
            subprocess.check_call(command, args, cwd=cwd, env=env)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print(e.stderr, end="")
            else:
                print(e.stderr)
            return e.returncode
    return 0
