def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self._scale
    else:
        try:
            other = float(other)
        except ValueError:
            raise ValueError("Invalid scale value: {}".format(other))
        if other <= 0:
            raise ValueError("Scale must be positive")
        self._scale = other
        self._rescale_errors()

def _rescale_errors(self):
    for field in self.fields:
        for error in field.errors:
            error.scale = self._scale

def __repr__(self):
    return "Graph(scale={})".format(self._scale)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)
    if len(metaclasses) == 0:
        return type
    elif len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("multiple metaclasses found")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is not __marker:
            return default
        else:
            raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_count = float("inf")
    min_key = None
    for key, (value, count) in self.items():
        if count < min_count:
            min_count = count
            min_key = key

    if min_key is None:
        raise KeyError("popitem(): dictionary is empty")

    value = self[min_key]
    del self[min_key]
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    oldest_key = None
    for key, _ in self.items():
        if oldest_key is None or self._order[key] < self._order[oldest_key]:
            oldest_key = key

    value = self[oldest_key]
    del self[oldest_key]
    return (oldest_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request.public_message:
            return True
        elif request.private_message:
            return True
        elif request.legacy_payload:
            return True
        else:
            return False
    except AttributeError:
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request.method == "POST" and request.headers.get("Content-Type") == "application/json":
            data = request.get_json()
            if data and "matrix" in data:
                return True
        return False
    except Exception as e:
        print(f"Error identifying request: {e}")
        return False

