def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    try:
        import infrared.core.utils.ansible as ansible
        import infrared.core.utils.exceptions as exceptions
    except ImportError:
        raise exceptions.InfraredError("Infrared is not installed.")

    if not isinstance(ir_workspace, infrared.core.workspace.Workspace):
        raise exceptions.InfraredError("Invalid Infrared Workspace object.")

    if not isinstance(ir_plugin, infrared.core.plugin.Plugin):
        raise exceptions.InfraredError("Invalid Infrared Plugin object.")

    if not playbook_path:
        raise exceptions.InfraredError("Playbook path is required.")

    if not os.path.exists(playbook_path):
        raise exceptions.InfraredError("Playbook path does not exist.")

    if verbose is not None and not isinstance(verbose, int):
        raise exceptions.InfraredError("Verbose level must be an integer.")

    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise exceptions.InfraredError("Extra vars must be a dictionary.")

    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise exceptions.InfraredError("Ansible args must be a dictionary.")

    ansible_playbook_path = os.path.join(ir_workspace.root, playbook_path)
    ansible_playbook_args = []

    if verbose is not None:
        ansible_playbook_args.append("-" + str(verbose))

    if extra_vars is not None:
        for key, value in extra_vars.items():
            ansible_playbook_args.append("-e")
            ansible_playbook_args.append(f"{key}={value}")

    if ansible_args is not None:
        for key, value in ansible_args.items():
            ansible_playbook_args.append(f"--{key}")
            ansible_playbook_args.append(value)

    ansible_playbook_args.append(ansible_playbook_path)

    try:
        ansible.run_playbook(ansible_playbook_args)
    except ansible.AnsibleError as e:
        raise exceptions.InfraredError(f"Ansible playbook execution failed: {e}")

    return True

def _convert_non_cli_args(self, parser_name, values_dict):
