    try:
        for key, value in values_dict.items():
            if key in self.arg_types[parser_name]:
                values_dict[key] = self.arg_types[parser_name][key](value)
    except KeyError:
        raise ValueError(f"Invalid argument name: {key}")
    except TypeError:
        raise ValueError(f"Invalid argument value: {value}")

